Q: Spring WebClient - Mockito NullPointerException body() is null A: <p>For those who stumble upon this thread and finding hard time to mock any downstream calls using webClient, I hope this will help in someway.</p>
<p>Actual code which calls the downstream:</p>
<pre><code>public Mono&lt;String&gt; getSomething(final MyContext myContext) {
    return myCustomWebClient
            .get()
            .uri(&quot;/my/downstream&quot;)
            .headers(headers -&gt; {
                headers.setBearerAuth(myContext.jwtToken());
                headers.set(&quot;header1&quot;, myContext.getHeader1());
            })
            .retrieve()
            .bodyToMono(String.class));
}
</code></pre>
<p>Now here is my TestClass to test this piece of code from: <code>Router</code> &gt; <code>Handler</code> &gt; <code>Any Other layer</code> &gt; <code>WebClient</code></p>
<pre><code>@TestPropertySource(properties = {
        &quot;spring.config.location=classpath:application-test.yml&quot;,
        &quot;spring.profiles.active=your-profile&quot;
})
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
public class MyClassTest {

    @Autowired
    protected WebTestClient webTestClient;

    @MockBean
    private WebClient myCustomWebClient;

    @MockBean
    private WebClient.ResponseSpec responseSpec;

    @MockBean
    @SuppressWarnings(&quot;rawtypes&quot;)
    private WebClient.RequestHeadersUriSpec requestHeadersUriSpec;

    @SuppressWarnings(&quot;rawtypes&quot;)
    private WebClient.RequestHeadersSpec requestHeadersSpec;

    @Test
    @SuppressWarnings(&quot;unchecked&quot;)
    void testCustomMethod() {
        Mockito.when(requestHeadersSpec.headers(Mockito.any()))
        .thenReturn(requestHeadersSpec);

        Mockito.when(requestHeadersSpec.retrieve())
        .thenReturn(responseSpec);

       Mockito.when(myCustomWebClient.get())
       .thenReturn(requestHeadersUriSpec);

       Mockito.when(requestHeadersUriSpec.uri(&quot;/my/downstream&quot;))
       .thenReturn(requestHeadersSpec);

       Mockito.when(responseSpec.bodyToMono(String.class))
       .thenReturn(Mono.empty());

       Mockito.when(myCustomWebClient.get().uri(&quot;/my/downstream&quot;)
       .headers(Mockito.any()).retrieve().bodyToMono(String.class))
       .thenReturn(Mono.empty());

        webTestClient.post()
            .uri(&quot;/your-end-point&quot;)
            .accept(MediaType.APPLICATION_JSON)
            .contentType(MediaType.APPLICATION_JSON)
            .header(&quot;header1&quot;, &quot;header1Value&quot;)
            .bodyValue(YourRequestClass.builder().build())
            .exchange()
            .expectStatus()
            .is5xxServerError()
            .expectBody(YourErrorClassPojo.class)
            .value(yourErrorResponsePojo -&gt; {
                // Assertions.assertEquals();
            })
            .consumeWith(System.out::println);
}
</code></pre>

Q: &#39;QML Connections: Cannot assign to non-existent Property&#39; despite the opposite being true A: <p>So, here is how the working main.cpp looks. I was mislead by the QmlContext that I was creating, and with help from @GrecKo's and jpnurmi's comments, I understood that I had to set the property for the root context.</p>

<pre><code>#include &lt;QGuiApplication&gt;
#include &lt;QQmlApplicationEngine&gt;
#include &lt;QQmlContext&gt;

#include "imageprovidervm.h"
#include "imagesource.h"

int main(int argc, char *argv[])
{
    QGuiApplication app(argc, argv);

    QQmlApplicationEngine engine;
    // QQmlContext *context = new QQmlContext(engine.rootContext());

    auto model = std::make_shared&lt;ImageSource&gt;();

    auto vm = new ImageProviderVM(model);
    engine.addImageProvider(QLatin1String("imageProvider"), vm);
    engine.rootContext()-&gt;setContextProperty("imageProvide", vm );

    model-&gt;generateImages();

    engine.load(QUrl(QStringLiteral("qrc:/view.qml")));

    return app.exec();
}
</code></pre>
